    export default {
        nuxtI18n: {
            paths: {
                fr: '/about-us',
                en: '/about-us',
            },
        },

        props: {
            content: {
                type: Object,
                default: () => {
                    return null;
                },
            },
        },

        data() {
            return {
                isShowReadMore: false,
                tabs: [
                    {
                        id: 'aboutUs',
                        title: 'About Us',
                    },
                    {
                        id: 'ourCulture',
                        title: 'Our Culture',
                    },
                    {
                        id: 'diverseEnvironment',
                        title: 'Diverse Environment',
                    },
                    {
                        id: 'driveForResults',
                        title: 'Drive for Results',
                    },
                    {
                        id: 'whyUs',
                        title: 'Why Us',
                    },
                    {
                        id: 'employmentAtVenturePlan',
                        title: 'Employment At Venture Plans',
                    },
                    {
                        id: 'readyToTalk',
                        title: 'Ready To Talk',
                    },
                ],
            };
        },

        head() {
            return {
                title: this.content?.metaFields[0]?.title,
                link: [
                    {
                        rel: 'canonical',
                        href: this.content?.metaFields[0]?.canonicalUrl
                            ? (process.env.FE_BASE_URL ? process.env.FE_BASE_URL : 'https://www.ventureplans.us') + this.content.metaFields[0].canonicalUrl
                            : (process.env.FE_BASE_URL ? process.env.FE_BASE_URL : 'https://www.ventureplans.us') + this.$route.path,
                    },
                ],
                meta: [
                    {
                        name: 'robots',
                        content: 'index, all',
                    },
                    {
                        hid: 'og:title',
                        property: 'og:title',
                        name: 'title',
                        content: this.content?.metaFields[0]?.title,
                    },
                    {
                        hid: 'og:image',
                        property: 'og:image',
                        content: this.content?.metaFields[0]?.socialImgUrl,
                    },
                    {
                        hid: 'og:description',

                        property: 'og:description',
                        content: this.content?.metaFields[0]?.description,
                    },
                    {
                        hid: 'description',
                        property: 'description',
                        name: 'description',
                        content: this.content?.metaFields[0]?.description,
                    },
                    {
                        hid: 'og:image:secure_url',
                        property: 'og:image:secure_url',
                        content: this.content?.metaFields[0]?.socialImgUrl,
                    },
                    {
                        hid: 'twitter:description',
                        property: 'twitter:description',
                        content: this.content?.metaFields[0]?.description,
                    },
                    {
                        hid: 'twitter:title',
                        property: 'twitter:title',
                        content: this.content?.metaFields[0]?.title,
                    },
                    {
                        hid: 'twitter:image',
                        property: 'twitter:image',
                        content: this.content?.metaFields[0]?.socialImgUrl,
                    },
                    {
                        hid: 'keywords',
                        property: 'keywords',
                        name: 'keywords',
                        content: this.content?.metaFields[0]?.keywords,
                    },
                ],
            };
        },

        computed: {
            section2Data() {
                return this.content?.section2Component?.data || [];
            },
            section4Data() {
                return this.content?.section4Component?.data || [];
            },
            section5Data() {
                return this.content?.section5Component?.data || [];
            },
            readyToTalkForm() {
                return this.content?.readyToTalkForm?.data?.attributes || { services: { data: [] } };
            },
        },
    };
